INSERT INTO "Permission"(id,code,description) VALUES
(gen_random_uuid(),'rfq.read','Read internal RFQ data'),(gen_random_uuid(),'rfq.manage','Manage RFQ lifecycle and recipients'),
(gen_random_uuid(),'quote.read','Read internal supplier quotes'),(gen_random_uuid(),'negotiation.read','Read internal negotiation history'),
(gen_random_uuid(),'negotiation.manage','Record internal negotiation events'),(gen_random_uuid(),'alternative_product.read','Read alternative product proposals'),
(gen_random_uuid(),'purchase_cost.read','Read approved purchase cost snapshots') ON CONFLICT(code) DO NOTHING;

REVOKE SELECT,INSERT,UPDATE ON rfqs,rfq_items,rfq_recipients,supplier_quotes,supplier_quote_revisions,supplier_quote_items,negotiation_sessions,negotiation_events,alternative_product_proposals,approved_purchase_cost_snapshots FROM sco_runtime;
DROP POLICY rfqs_internal ON rfqs; DROP POLICY rfq_items_internal ON rfq_items; DROP POLICY rfq_recipients_internal ON rfq_recipients;
DROP POLICY supplier_quotes_internal ON supplier_quotes; DROP POLICY supplier_quote_revisions_internal ON supplier_quote_revisions; DROP POLICY supplier_quote_items_internal ON supplier_quote_items;
DROP POLICY negotiation_sessions_internal ON negotiation_sessions; DROP POLICY negotiation_events_internal ON negotiation_events;
DROP POLICY alternative_product_proposals_internal ON alternative_product_proposals; DROP POLICY approved_purchase_cost_snapshots_internal ON approved_purchase_cost_snapshots;
REVOKE SELECT,UPDATE ON alternative_product_proposals FROM sco_internal_executor;

CREATE FUNCTION public.internal_has_capability(p_actor uuid,p_code text) RETURNS boolean LANGUAGE sql SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM public."CompanyMembership" cm JOIN public."Company" c ON c.id=cm."companyId" AND c.type='SCO' AND c.status='ACTIVE' JOIN public."MembershipRole" mr ON mr.membership_id=cm.id JOIN public."RolePermission" rp ON rp.role_id=mr.role_id JOIN public."Permission" p ON p.id=rp.permission_id WHERE cm."userId"=p_actor AND cm.status='ACTIVE' AND p.code=p_code) $$;
REVOKE ALL ON FUNCTION public.internal_has_capability(uuid,text) FROM PUBLIC,sco_internal_executor;

CREATE FUNCTION public.internal_rfq_get(p_actor uuid,p_id uuid) RETURNS SETOF public.rfqs LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT r.* FROM public.rfqs r WHERE r.id=p_id AND public.internal_has_capability(p_actor,'rfq.read') $$;
CREATE FUNCTION public.internal_rfq_items(p_actor uuid,p_id uuid) RETURNS SETOF public.rfq_items LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT i.* FROM public.rfq_items i WHERE i.rfq_id=p_id AND public.internal_has_capability(p_actor,'rfq.read') $$;
CREATE FUNCTION public.internal_rfq_recipients(p_actor uuid,p_id uuid) RETURNS SETOF public.rfq_recipients LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT x.* FROM public.rfq_recipients x WHERE x.rfq_id=p_id AND public.internal_has_capability(p_actor,'rfq.read') $$;
CREATE FUNCTION public.internal_rfq_list(p_actor uuid,p_limit int,p_offset int) RETURNS SETOF public.rfqs LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT r.* FROM public.rfqs r WHERE public.internal_has_capability(p_actor,'rfq.read') ORDER BY r.created_at DESC LIMIT LEAST(GREATEST(p_limit,1),100) OFFSET GREATEST(p_offset,0) $$;
CREATE FUNCTION public.internal_rfq_create(p_actor uuid,p_execution_items uuid[],p_expires timestamptz,p_notes text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_id uuid:=gen_random_uuid(); BEGIN IF NOT public.internal_has_capability(p_actor,'rfq.create') THEN RAISE EXCEPTION 'RFQ_CREATE_FORBIDDEN'; END IF; IF p_execution_items IS NULL OR cardinality(p_execution_items)=0 THEN RAISE EXCEPTION 'RFQ_ITEMS_REQUIRED'; END IF; INSERT INTO public.rfqs(id,created_by,expires_at,internal_notes) VALUES(v_id,p_actor,p_expires,p_notes); INSERT INTO public.rfq_items(rfq_id,execution_item_id,company_id,project_id,procurement_need_id,product_identity_id,requested_quantity,unit_id) SELECT v_id,e.id,e.company_id,e.project_id,e.procurement_need_id,e.product_identity_id,e.remaining_quantity,e.unit_id FROM public.procurement_execution_items e WHERE e.id=ANY(p_execution_items) AND e.remaining_quantity>0; IF (SELECT count(*) FROM public.rfq_items WHERE rfq_id=v_id)<>cardinality(p_execution_items) THEN RAISE EXCEPTION 'RFQ_EXECUTION_ITEM_INVALID'; END IF; RETURN v_id; END $$;
CREATE FUNCTION public.internal_rfq_transition(p_actor uuid,p_id uuid,p_next "RFQStatus") RETURNS TABLE(id uuid,status "RFQStatus") LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_from "RFQStatus"; BEGIN IF NOT public.internal_has_capability(p_actor,'rfq.manage') THEN RAISE EXCEPTION 'RFQ_MANAGE_FORBIDDEN'; END IF; SELECT r.status INTO v_from FROM public.rfqs r WHERE r.id=p_id FOR UPDATE; IF v_from IS NULL THEN RAISE EXCEPTION 'RFQ_NOT_FOUND'; END IF; IF NOT ((v_from='DRAFT' AND p_next IN ('READY_TO_SEND','CANCELLED')) OR (v_from='READY_TO_SEND' AND p_next IN ('ISSUED','CANCELLED')) OR (v_from='ISSUED' AND p_next IN ('RESPONSES_PENDING','CANCELLED')) OR (v_from='RESPONSES_PENDING' AND p_next IN ('EVALUATION','EXPIRED','CANCELLED')) OR (v_from='EVALUATION' AND p_next IN ('CLOSED','CANCELLED'))) THEN RAISE EXCEPTION 'INVALID_RFQ_TRANSITION'; END IF; RETURN QUERY UPDATE public.rfqs r SET status=p_next,updated_at=now(),issued_by=CASE WHEN p_next='ISSUED' THEN p_actor ELSE r.issued_by END,issued_at=CASE WHEN p_next='ISSUED' THEN now() ELSE r.issued_at END WHERE r.id=p_id RETURNING r.id,r.status; END $$;
CREATE FUNCTION public.internal_rfq_add_recipient(p_actor uuid,p_rfq uuid,p_source uuid) RETURNS TABLE(id uuid,status "RFQRecipientStatus") LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_supplier uuid; BEGIN IF NOT public.internal_has_capability(p_actor,'rfq.manage') THEN RAISE EXCEPTION 'RFQ_MANAGE_FORBIDDEN'; END IF; SELECT ps.supplier_company_id INTO v_supplier FROM public.rfqs r JOIN public.rfq_items ri ON ri.rfq_id=r.id JOIN public.product_identities pi ON pi.id=ri.product_identity_id JOIN public.purchase_sources ps ON ps.id=p_source AND ps.status='ACTIVE' JOIN public.company_partnerships sp ON sp.id=ps.supplier_partnership_id AND sp.type='SUPPLIER_PARTNERSHIP' AND sp.status='ACTIVE' JOIN public.supplier_qualifications sq ON sq.supplier_partnership_id=sp.id AND sq.status='ACTIVE' JOIN public.supplier_category_capabilities scc ON scc.supplier_partnership_id=sp.id AND scc.category_id=pi.category_id AND scc.status='ACTIVE' WHERE r.id=p_rfq AND r.status<>'CLOSED' LIMIT 1; IF v_supplier IS NULL THEN RAISE EXCEPTION 'SOURCE_NOT_ELIGIBLE'; END IF; RETURN QUERY INSERT INTO public.rfq_recipients(rfq_id,purchase_source_id,supplier_company_id) VALUES(p_rfq,p_source,v_supplier) RETURNING rfq_recipients.id,rfq_recipients.status; END $$;

CREATE FUNCTION public.internal_quote_get(p_actor uuid,p_id uuid) RETURNS SETOF public.supplier_quotes LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT q.* FROM public.supplier_quotes q WHERE q.id=p_id AND public.internal_has_capability(p_actor,'quote.read') $$;
CREATE FUNCTION public.internal_quote_revisions(p_actor uuid,p_quote uuid) RETURNS SETOF public.supplier_quote_revisions LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT r.* FROM public.supplier_quote_revisions r WHERE r.supplier_quote_id=p_quote AND public.internal_has_capability(p_actor,'quote.read') ORDER BY r.revision_number $$;
CREATE FUNCTION public.internal_quote_items(p_actor uuid,p_revision uuid) RETURNS SETOF public.supplier_quote_items LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT i.* FROM public.supplier_quote_items i WHERE i.revision_id=p_revision AND public.internal_has_capability(p_actor,'quote.read') $$;
CREATE FUNCTION public.internal_quote_record(p_actor uuid,p_rfq uuid,p_source uuid,p_supplier uuid,p_reference text,p_currency text,p_items jsonb) RETURNS TABLE(quote_id uuid,revision_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE q uuid:=gen_random_uuid(); r uuid:=gen_random_uuid(); x jsonb; BEGIN IF NOT public.internal_has_capability(p_actor,'quote.record') THEN RAISE EXCEPTION 'QUOTE_RECORD_FORBIDDEN'; END IF; INSERT INTO public.supplier_quotes(id,rfq_id,purchase_source_id,supplier_company_id,quote_reference,created_by) VALUES(q,p_rfq,p_source,p_supplier,p_reference,p_actor); INSERT INTO public.supplier_quote_revisions(id,supplier_quote_id,revision_number,initiated_by,currency_code) VALUES(r,q,1,p_actor,p_currency); FOR x IN SELECT * FROM jsonb_array_elements(p_items) LOOP INSERT INTO public.supplier_quote_items(revision_id,rfq_item_id,product_identity_id,quoted_quantity,unit_price_excl_tax) VALUES(r,(x->>'rfqItemId')::uuid,(x->>'productIdentityId')::uuid,(x->>'quantity')::numeric,(x->>'unitPrice')::numeric); END LOOP; RETURN QUERY SELECT q,r; END $$;
CREATE FUNCTION public.internal_quote_revise(p_actor uuid,p_quote uuid,p_currency text,p_reason text,p_items jsonb) RETURNS TABLE(id uuid,revision_number int) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE prior record; r uuid:=gen_random_uuid(); n int; x jsonb; BEGIN IF NOT public.internal_has_capability(p_actor,'quote.revise') THEN RAISE EXCEPTION 'QUOTE_REVISE_FORBIDDEN'; END IF; SELECT qr.id,qr.revision_number INTO prior FROM public.supplier_quote_revisions qr WHERE qr.supplier_quote_id=p_quote ORDER BY qr.revision_number DESC LIMIT 1 FOR UPDATE; IF prior.id IS NULL THEN RAISE EXCEPTION 'QUOTE_NOT_FOUND'; END IF; n:=prior.revision_number+1; INSERT INTO public.supplier_quote_revisions(id,supplier_quote_id,revision_number,supersedes_revision_id,initiated_by,reason,currency_code) VALUES(r,p_quote,n,prior.id,p_actor,p_reason,p_currency); FOR x IN SELECT * FROM jsonb_array_elements(p_items) LOOP INSERT INTO public.supplier_quote_items(revision_id,rfq_item_id,product_identity_id,quoted_quantity,unit_price_excl_tax) VALUES(r,(x->>'rfqItemId')::uuid,(x->>'productIdentityId')::uuid,(x->>'quantity')::numeric,(x->>'unitPrice')::numeric); END LOOP; RETURN QUERY SELECT r,n; END $$;

CREATE FUNCTION public.internal_negotiation_events(p_actor uuid,p_session uuid) RETURNS SETOF public.negotiation_events LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT e.* FROM public.negotiation_events e WHERE e.session_id=p_session AND public.internal_has_capability(p_actor,'negotiation.read') ORDER BY e.created_at $$;
CREATE FUNCTION public.internal_negotiation_record(p_actor uuid,p_rfq uuid,p_revision uuid,p_direction text,p_event text,p_reason text,p_metadata jsonb,p_correlation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE s uuid; e uuid; BEGIN IF NOT public.internal_has_capability(p_actor,'negotiation.manage') THEN RAISE EXCEPTION 'NEGOTIATION_MANAGE_FORBIDDEN'; END IF; SELECT n.id INTO s FROM public.negotiation_sessions n WHERE n.rfq_id=p_rfq AND n.status='OPEN' LIMIT 1 FOR UPDATE; IF s IS NULL THEN s:=gen_random_uuid(); INSERT INTO public.negotiation_sessions(id,rfq_id,created_by) VALUES(s,p_rfq,p_actor); END IF; e:=gen_random_uuid(); INSERT INTO public.negotiation_events(id,session_id,supplier_quote_revision_id,direction,event_type,reason,metadata,actor_user_id,correlation_id) VALUES(e,s,p_revision,p_direction,p_event,p_reason,COALESCE(p_metadata,'{}'),p_actor,p_correlation); RETURN e; END $$;

CREATE FUNCTION public.internal_alternative_product_get(p_actor uuid,p_id uuid) RETURNS SETOF public.alternative_product_proposals LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT a.* FROM public.alternative_product_proposals a WHERE a.id=p_id AND public.internal_has_capability(p_actor,'alternative_product.read') $$;
CREATE FUNCTION public.internal_alternative_product_review(p_actor uuid,p_id uuid,p_decision text,p_reason text) RETURNS TABLE(id uuid,status text,reviewed_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.internal_has_capability(p_actor,'alternative_product.review') THEN RAISE EXCEPTION 'ALTERNATIVE_REVIEW_FORBIDDEN'; END IF; IF btrim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'REVIEW_REASON_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.alternative_product_proposals a WHERE a.id=p_id AND a.status='PENDING_REVIEW' FOR UPDATE) THEN RAISE EXCEPTION 'ALTERNATIVE_PROPOSAL_NOT_PENDING'; END IF; RETURN QUERY UPDATE public.alternative_product_proposals a SET status=p_decision,reviewed_by=p_actor,reviewed_at=now(),decision_reason=p_reason WHERE a.id=p_id RETURNING a.id,a.status,a.reviewed_at; END $$;

CREATE FUNCTION public.internal_purchase_cost_get(p_actor uuid,p_id uuid) RETURNS SETOF public.approved_purchase_cost_snapshots LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT s.* FROM public.approved_purchase_cost_snapshots s WHERE s.id=p_id AND public.internal_has_capability(p_actor,'purchase_cost.read') $$;
CREATE FUNCTION public.internal_purchase_cost_list(p_actor uuid,p_item uuid) RETURNS SETOF public.approved_purchase_cost_snapshots LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT s.* FROM public.approved_purchase_cost_snapshots s WHERE s.rfq_item_id=p_item AND public.internal_has_capability(p_actor,'purchase_cost.read') ORDER BY s.created_at $$;
CREATE FUNCTION public.internal_purchase_cost_approve(p_actor uuid,p_item uuid,p_revision uuid,p_source uuid,p_supplier uuid,p_product uuid,p_quantity numeric,p_currency text,p_unit_cost numeric,p_reason text,p_self boolean,p_correlation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_creator uuid; v_valid date; v_id uuid:=gen_random_uuid(); BEGIN IF btrim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'APPROVAL_REASON_REQUIRED'; END IF; IF NOT public.internal_has_capability(p_actor,'purchase_cost.approve') THEN RAISE EXCEPTION 'PURCHASE_COST_APPROVAL_FORBIDDEN'; END IF; SELECT r.initiated_by,r.valid_until INTO v_creator,v_valid FROM public.supplier_quote_revisions r WHERE r.id=p_revision; IF v_creator IS NULL THEN RAISE EXCEPTION 'REVISION_NOT_FOUND'; END IF; IF v_valid IS NOT NULL AND v_valid<current_date THEN RAISE EXCEPTION 'QUOTE_REVISION_EXPIRED'; END IF; IF v_creator=p_actor AND (NOT p_self OR NOT public.internal_has_capability(p_actor,'purchase_cost.self_approve')) THEN RAISE EXCEPTION 'SEPARATION_OF_DUTIES_REQUIRED'; END IF; INSERT INTO public.approved_purchase_cost_snapshots(id,rfq_item_id,supplier_quote_revision_id,purchase_source_id,supplier_company_id,product_identity_id,approved_quantity,currency_code,unit_purchase_cost,amount_excl_tax,amount_incl_tax,status,approved_by,approved_at,approval_reason,correlation_id,created_by) VALUES(v_id,p_item,p_revision,p_source,p_supplier,p_product,p_quantity,p_currency,p_unit_cost,p_quantity*p_unit_cost,p_quantity*p_unit_cost,'APPROVED',p_actor,now(),p_reason,p_correlation,p_actor); RETURN v_id; END $$;

CREATE FUNCTION public.internal_purchase_source_get(p_actor uuid,p_id uuid) RETURNS TABLE(id uuid,supplier_company_id uuid,source_code text,status "PurchaseSourceStatus") LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT p.id,p.supplier_company_id,p.source_code,p.status FROM public.purchase_sources p WHERE p.id=p_id AND public.internal_has_capability(p_actor,'purchase_source.read') $$;

DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'internal_%' AND p.proname<>'internal_has_capability' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.sig); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO sco_internal_executor',f.sig); END LOOP; END $$;
